var browser = {
  _canUse: null,
  canUse: function (property) {
    if (!this._canUse) {
      this._canUse = document.createElement("div");
    }
    var style = this._canUse.style;
    var prop = property.charAt(0).toUpperCase() + property.slice(1);
    return (
      property in style ||
      "Moz" + prop in style ||
      "Webkit" + prop in style ||
      "O" + prop in style ||
      "ms" + prop in style
    );
  }
};
